-- ============================================================
-- 种子数据: sys_ai_model（AI 模型配置表）
-- 模块: 基础模块-AI模型管理
-- ============================================================
-- 正式模型清单：
--   chat:      gpt-4o-mini(openai) / qwen3-0.6b(内置本地) / deepseek-v4-flash(deepseek)
--   embedding: bge-m3(内置本地, 1024维) —— 知识库创建时按 sys_ai_model 注册表校验
--              （model_type=embedding 且启用，走 ai:model:list 缓存），不设代码白名单；
--              本地向量服务(8992 /v1/embeddings)接受任意模型名。
--              text-embedding-3-small/large(openai, 1536/3072维) 为历史知识库可选模型，
--              播种保持注册表内可用；
--              本地向量模型真实标识 qwen3-embedding-0.6b 由后端 ensure_local_models
--              幂等播种为停用注册记录(status=0)，不在此清单。
--   asr:       sensevoice(stream) / paraformer(offline)（内置本地，id 300/301）
--   tts:       huayan（内置本地，id 302）
--   image_edit: 由 sys_algorithm 有效行同源静态化（provider=local-modal，id 400 起，共 85 行）——
--              与阶段1 迁移第⑤段逐列一致（model_id=算法规范 slug 如 aecrnet / c2pnet-its；
--              完整映射表见 config/sql/migration/2026-09-29_unified_model_management_stage1_mapping.md）。
--   说明：全部三类（asr/tts/image_edit）都静态落，保证全新环境（schema+data 全量重建、不跑迁移）
--      与已执行迁移的 dev 库逻辑一致、`default_model.*` 不出现悬空引用；
--      迁移对已存在的 (model_id, provider_id) 行按存在性判断跳过，两者不会重复插入。
-- 说明：
--   1. 本文件由 rebuild_mysql.py --import 全量同步（先清表再导入），
--      历史测试残留（SDK 集成测试创建的 test_* 模型）不在此清单内。
--   2. id 显式固定：deepseek-v4-flash.fallback_model_id=70 引用 qwen3-0.6b，
--      固定 id 保证降级引用有效；embedding 用新 id=200 避免与既有自增冲突。
--   3. rerank 模型本地暂无能力，不配置伪模型，知识库 rerank 保持关闭。
--   4. **仅供全新库**：plain INSERT + 固定主键，供全新库全量导入；存量库重跑会 `ERROR 1062` 中止
--      （且小号 id 可能已被测试造号如 `favmodel_*`/`test_model_*` 占用）。存量环境（dev/pre）
--      不要重跑本文件、也不用 `--import sys_ai_model.sql`（会整表 DELETE）；改用幂等 migration
--      `config/sql/migration/2026-10-01_seed_volcano_providers_models.sql`（业务键守卫、不写死 id）。
-- ============================================================
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;


-- 语音模型（原 sys_voice_model 迁入统一注册表，provider=local-voice）：
--   sensevoice(asr/stream) / paraformer(asr/offline) / huayan(tts)；运行时工件（onnx 路径等）不落库，
--   由 dehaze-voice /v1/models 按 model_id 服务端解析。
--   注：未列出的列取 schema 默认值，与迁移 SQL（2026-09-29_unified_model_management_stage1.sql）逐列一致。

-- image_edit 模型（阶段1 迁移产物同源静态化，provider=local-modal）：与迁移 SQL 第⑤段逐列一致
--   （model_id=算法规范 slug；同 weights path 的重复算法行合并，保留 id 最小者）

-- 第三方模型（火山引擎方案）：
--   id=500 chat       方舟 doubao-seed-2-0-mini-260428（低优档，32k 内最低价；prompt cache 命中价更低）
--   id=501 embedding  硅基流动 BAAI/bge-m3（dimension=1024，创建后不可改；task_tags=["text"]）
--   id=502 rerank     硅基流动 BAAI/bge-reranker-v2-m3
--   id=503 asr        火山 bigmodel（与协议首帧 model_name 一致；离线识别复用流式端点，同样标 stream）
--   id=504 tts        火山 volc-tts-2-0（仅平台路由标识，火山 TTS 请求体不携带该字段；音色由请求参数 voice 决定）
--   id=505 chat       硅基流动 Qwen/Qwen3-8B（轻量中文对话，支持流式与工具调用；硅基流动免费档，作默认测试模型候选）
--   注册即可用（status=1），但不设平台默认模型——切换默认模型见 migration 的 opt-in 步骤（密钥就位后执行）

SET FOREIGN_KEY_CHECKS = 1;
